package com.bank.control;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    // BUGGY: the finally return overrides the try return AND swallows exceptions.
    // Never do this in real code — shown only to demonstrate the defect.
    public BigDecimal buggyTransfer(Account from, Account to, BigDecimal amount) {
        try {
            from.debit(amount);          // may throw IllegalStateException
            to.credit(amount);
            return from.getBalance();    // the CORRECT result we intend to return
        } finally {
            // "always return something safe" — this is the bug.
            // It discards the try's value and eats any exception thrown above.
            return BigDecimal.valueOf(-1);
        }
    }

    // CORRECT: finally is used ONLY for cleanup, never to return.
    // We simulate a resource (a lock) that must always be released.
    public BigDecimal correctTransfer(Account from, Account to, BigDecimal amount) {
        boolean lockHeld = acquireLock(from.getAccountId());
        try {
            from.debit(amount);          // may throw — and will propagate correctly
            to.credit(amount);
            log.info(() -> "Transfer " + amount + " from " + from.getAccountId()
                    + " to " + to.getAccountId() + " SUCCESS");
            return from.getBalance();    // the real, correct result
        } finally {
            if (lockHeld) releaseLock(from.getAccountId()); // cleanup ONLY, no return
        }
    }

    private boolean acquireLock(String id) { log.fine(() -> "Lock acquired on " + id); return true; }
    private void releaseLock(String id) { log.fine(() -> "Lock released on " + id); }
}
