package com.bank.control;

import java.math.BigDecimal;
import java.util.logging.*;

public class FinallyReturnDemo {
    private static final Logger log = Logger.getLogger(FinallyReturnDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TransferService service = new TransferService();

        // Scenario A: normal transfer of 50000 — the buggy method lies about the result.
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        BigDecimal buggyResult = service.buggyTransfer(rajesh, priya, new BigDecimal("50000"));
        log.warning(() -> "BUGGY reported new balance: " + buggyResult
                + " but Rajesh ACTUAL balance is: " + rajesh.getBalance());

        Account rajesh2 = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya2  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        BigDecimal correctResult = service.correctTransfer(rajesh2, priya2, new BigDecimal("50000"));
        log.info(() -> "CORRECT reported new balance: " + correctResult
                + " and Rajesh ACTUAL balance is: " + rajesh2.getBalance());

        // Scenario B: insufficient funds — buggy swallows the exception, correct propagates it.
        Account poor = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000"));
        Account priya3 = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        BigDecimal swallowed = service.buggyTransfer(poor, priya3, new BigDecimal("50000"));
        log.severe(() -> "BUGGY swallowed the InsufficientFunds error and returned: " + swallowed);

        try {
            service.correctTransfer(poor, priya3, new BigDecimal("50000"));
        } catch (IllegalStateException e) {
            log.log(Level.SEVERE, "CORRECT correctly propagated the failure", e);
        }
    }
}
